#include <stdio.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <errno.h>

// Global flag indicating umask has been set from the command line
int umask_set_from_cmdline = 0;

mode_t set_umask_from_str(const char *optarg) {
    char *endptr;
    long umask_value;

    errno = 0;
    umask_value = strtol(optarg, &endptr, 8);

    // Check for conversion errors
    if (errno != 0 || endptr == optarg || *endptr != '\0') {
        fprintf(stderr, "Invalid umask value: %s\n", optarg);
        return 0;
    }

    // Check for out-of-range values
    if (umask_value < 0 || umask_value > 0777) {
        fprintf(stderr, "Umask value out of range: %s\n", optarg);
        return 0;
    }

    mode_t new_umask = (mode_t)umask_value;
    umask(new_umask);
    umask_set_from_cmdline = 1;
    return new_umask;
}
